import random

def solve_optimal(intervals):
    total = 0
    current_end = None
    current_start = None
    for start, end in sorted(intervals):
        if current_end is None or start > current_end:
            if current_end is not None:
                total += current_end - current_start
            current_start, current_end = start, end
        else:
            current_end = max(current_end, end)
    if current_end is not None:
        total += current_end - current_start
    return total

def solve_brute(intervals):
    cells = set()
    for start, end in intervals:
        for x in range(start, end):
            cells.add(x)
    return len(cells)

def gen(rng, size):
    count = rng.randint(1, {"tiny": 3, "small": 7, "large": 25}[size])
    out = []
    for _ in range(count):
        a = rng.randint(0, 40)
        out.append([a, a + rng.randint(1, 12)])
    return [out]

def validate(args):
    intervals = args[0]
    return 1 <= len(intervals) <= 1000 and all(len(p) == 2 and 0 <= p[0] < p[1] <= 10**4 for p in intervals)
